use anyhow::{Context, Result};

use super::{revision::RollbackStateFrontier, RollbackOutcome};
use crate::program_module::runtime::effects::recovery_is_fenced;
use crate::program_module::runtime::{EpochState, SlotState};

pub(super) fn unresolved_effect_outcome(state: &SlotState) -> Option<RollbackOutcome> {
    recovery_is_fenced(state).then_some(RollbackOutcome {
        status: "rollback_blocked_unresolved_effect",
        message: Some("unresolved effect fences automatic rollback".to_owned()),
        record_cid: None,
    })
}

pub(super) fn promote(
    state: &mut SlotState,
    failed_epoch: u64,
    rollback_epoch: u64,
    record_cid: &str,
    module_cid: String,
    fields: RollbackStateFrontier,
) -> Result<()> {
    state
        .epochs
        .get_mut(&failed_epoch)
        .context("runtime current epoch is missing")?
        .lifecycle = "draining";
    state.epochs.insert(
        rollback_epoch,
        EpochState {
            record_cid: record_cid.to_owned(),
            module_cid,
            lifecycle: "current",
            active_leases: 0,
            rollback_module_cid: None,
            state_cid: fields.state_cid,
            state_extension_cid: fields.extension_cid,
            migration_receipt_cid: None,
            state_revision_cid: fields.revision_cid,
            state_revision: fields.revision,
            rollback_state_cid: None,
            rollback_state_extension_cid: None,
        },
    );
    state.current_record_cid = record_cid.to_owned();
    state.current_epoch = rollback_epoch;
    state.frontier_health = "ready";
    Ok(())
}

